/// Bộ nạp lớp tạm cho [CharacterView] ở màn mở đầu: giải mã khối
/// xám thành [MemoryImage]. Đường dẫn lạ (không có trong bảng tạm)
/// thì trả về ảnh trong suốt 1x1 để lớp đó coi như trống, không vỡ
/// cả nhân vật.
ImageProvider placeholderLayerLoader(String assetPath) {
  final b64 = placeholderLayerBase64[assetPath];
  if (b64 == null) return MemoryImage(Uint8List.fromList(_transparentPixel));
  return MemoryImage(base64Decode(b64));
}

